import { encodeBase64Url } from './base64url.mjs';
import { signHs256 } from './hs256-openssl.mjs';
import { encodeJsonSegment } from './json-segment.mjs';

const DEFAULT_HEADER = Object.freeze({
  alg: 'HS256',
  typ: 'JWT',
});

export function encodeToken(payload, secret) {
  const headerSegment = encodeJsonSegment(DEFAULT_HEADER);
  const payloadSegment = encodeJsonSegment(payload);
  const signingInput = `${headerSegment}.${payloadSegment}`;
  const signatureSegment = encodeBase64Url(signHs256(signingInput, secret));

  return `${signingInput}.${signatureSegment}`;
}

