import { spawnSync } from 'node:child_process';

export function signHs256(signingInput, secret) {
  const result = spawnSync('openssl', ['dgst', '-sha256', '-hmac', secret, '-binary'], {
    input: Buffer.from(signingInput, 'utf8'),
    encoding: null,
  });

  if (result.error) {
    throw result.error;
  }

  if (result.status !== 0) {
    const stderrText = (result.stderr ?? Buffer.alloc(0)).toString('utf8').trim();
    throw new Error(stderrText || `openssl exited with status ${result.status}`);
  }

  return result.stdout;
}

