import { getErrorText, getHelpText } from './messages.mjs';
import { getProgramName } from './program-name.mjs';

const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;
const HELP_OPTION = '-h';
const HELP_LONG_OPTION = '--help';
const PAYLOAD_LONG_OPTION = '--payload';
const LONG_OPTIONS = [HELP_LONG_OPTION, PAYLOAD_LONG_OPTION];

function matchLongOption(optionToken) {
  if (optionToken === '--') {
    return null;
  }

  const matches = LONG_OPTIONS.filter((candidate) => candidate.startsWith(optionToken));
  return matches.length === 1 ? matches[0] : null;
}

function parseShortHelpToken(token) {
  if (token === HELP_OPTION) {
    return { kind: 'help', explicitValue: null };
  }

  if (!token.startsWith(HELP_OPTION) || token === '-') {
    return null;
  }

  const explicitValue = token.startsWith('-h=') ? token.slice(3) : token.slice(2);
  return { kind: 'help', explicitValue };
}

function parseOptionToken(token) {
  const shortHelp = parseShortHelpToken(token);
  if (shortHelp !== null) {
    return shortHelp;
  }

  if (!token.startsWith('--')) {
    return null;
  }

  const separatorIndex = token.indexOf('=');
  const optionToken = separatorIndex === -1 ? token : token.slice(0, separatorIndex);
  const explicitValue = separatorIndex === -1 ? null : token.slice(separatorIndex + 1);
  const matchedOption = matchLongOption(optionToken);

  if (matchedOption === HELP_LONG_OPTION) {
    return { kind: 'help', explicitValue };
  }

  if (matchedOption === PAYLOAD_LONG_OPTION) {
    return { kind: 'payload', explicitValue };
  }

  return null;
}

function isOptionLikeValue(token) {
  if (token === undefined || token === '-') {
    return false;
  }

  if (!token.startsWith('-')) {
    return false;
  }

  return !NEGATIVE_NUMBER_PATTERN.test(token);
}

export function parseCommandLine(argv = process.argv) {
  const programName = getProgramName(argv);
  const tokens = argv.slice(2);
  const extras = [];
  let payload;

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];
    const option = parseOptionToken(token);

    if (option === null) {
      extras.push(token);
      continue;
    }

    if (option.kind === 'help') {
      if (option.explicitValue !== null) {
        return {
          kind: 'error',
          exitCode: 2,
          text: getErrorText(
            programName,
            `argument -h/--help: ignored explicit argument '${option.explicitValue}'`,
          ),
        };
      }

      return {
        kind: 'help',
        exitCode: 0,
        text: getHelpText(programName),
      };
    }

    if (option.explicitValue !== null) {
      payload = option.explicitValue;
      continue;
    }

    const nextToken = tokens[index + 1];
    if (nextToken === undefined || isOptionLikeValue(nextToken)) {
      return {
        kind: 'error',
        exitCode: 2,
        text: getErrorText(programName, 'argument --payload: expected one argument'),
      };
    }

    payload = nextToken;
    index += 1;
  }

  if (payload === undefined) {
    return {
      kind: 'error',
      exitCode: 2,
      text: getErrorText(programName, 'the following arguments are required: --payload'),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      exitCode: 2,
      text: getErrorText(programName, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return {
    kind: 'ok',
    exitCode: 0,
    payload,
  };
}

